// Bounded exact integer models. BigInt avoids JavaScript's signed 32-bit operators.
function integer(n,min,max){if(!Number.isSafeInteger(n)||n<min||n>max)throw new RangeError('Integer outside model domain');return n;}
export function word(n,width=8){integer(width,1,16);integer(n,0,2**width-1);return BigInt(n).toString(2).padStart(width,'0');}
export function signedWord(n,width=8){word(n,width);return n>=2**(width-1)?n-2**width:n;}
export function xorTrace(values,width=4){integer(width,1,16);values.forEach(n=>word(n,width));let accumulator=0n;const frames=[{values:[...values],index:null,accumulator:0,processed:0}];for(let i=0;i<values.length;i++){accumulator^=BigInt(values[i]);frames.push({values:[...values],index:i,accumulator:Number(accumulator),processed:i+1});}return frames;}
export function addTrace(a,b,width=8){word(a,width);word(b,width);const mask=(1n<<BigInt(width))-1n,total=(BigInt(a)+BigInt(b))&mask,frames=[];let x=BigInt(a),y=BigInt(b);while(true){frames.push({a:Number(x),b:Number(y),width,total:Number(total),done:y===0n});if(y===0n)break;const carry=(x&y)<<1n;x=(x^y)&mask;y=carry&mask;if(frames.length>width+1)throw new Error('Carry failed to terminate');}return frames;}
export function alignment(x,a){integer(x,0,1_000_000);integer(a,1,65536);const A=BigInt(a),X=BigInt(x);if((A&(A-1n))!==0n)throw new RangeError('Alignment must be a positive power of two');return {x,a,k:Math.log2(a),offset:x%a,down:Number(X&~(A-1n)),up:Number((X+A-1n)&~(A-1n)),added:x+a-1};}
export function spiralTrace(rows,cols){integer(rows,0,8);integer(cols,0,8);let top=0,bottom=rows-1,left=0,right=cols-1;const output=[],frames=[];const save=(message,current=null)=>frames.push({rows,cols,top,bottom,left,right,current,output:[...output],message});const visit=(r,c)=>{const index=r*cols+c;output.push(index);save(`Emit (${r},${c}), value ${index}.`,index);};save('The inclusive boundaries enclose every unvisited cell.');while(top<=bottom&&left<=right){for(let c=left;c<=right;c++)visit(top,c);top++;save('Retire the top boundary.');for(let r=top;r<=bottom;r++)visit(r,right);right--;save('Retire the right boundary.');if(top<=bottom){for(let c=right;c>=left;c--)visit(bottom,c);bottom--;save('Retire the bottom boundary after the row check.');}if(left<=right){for(let r=bottom;r>=top;r--)visit(r,left);left++;save('Retire the left boundary after the column check.');}}save('The bounds no longer enclose a cell; traversal is complete.');return frames;}
